"use client";

import { useEffect, useState } from "react";
import { pythonQuestions } from "/pages/test/pythonQuestions.js";

const STORAGE_KEY = "python_test_state_v2";

export default function PythonTest() {
  /* ---------------- STATES ---------------- */
  const [step, setStep] = useState("login"); // login | instructions | test | submitted
  const [timer, setTimer] = useState(20 * 60);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [tabViolated, setTabViolated] = useState(false);

  /* ---------------- LOAD SAVED STATE ---------------- */
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setStep(data.step);
      setTimer(data.timer);
      setQuestions(data.questions || []);
      setAnswers(data.answers || {});
    }
  }, []);

  /* ---------------- SAVE STATE ---------------- */
  useEffect(() => {
    if (step === "test") {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ step, timer, questions, answers })
      );
    }
  }, [step, timer, questions, answers]);

  /* ---------------- RANDOM 50 QUESTIONS ---------------- */
  const generateQuestions = () => {
    const shuffled = [...pythonQuestions].sort(() => 0.5 - Math.random());
    setQuestions(shuffled.slice(0, 50));
  };

  /* ---------------- TIMER ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const interval = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          submitTest(true);
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [step]);

  /* ---------------- SECURITY ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const block = (e) => e.preventDefault();
    document.addEventListener("copy", block);
    document.addEventListener("paste", block);
    document.addEventListener("contextmenu", block);

    const visibilityHandler = () => {
      if (document.hidden && !tabViolated) {
        setTabViolated(true);
        alert("Tab switching is not allowed. Test will be submitted.");
        submitTest(true);
      }
    };

    document.addEventListener("visibilitychange", visibilityHandler);

    return () => {
      document.removeEventListener("copy", block);
      document.removeEventListener("paste", block);
      document.removeEventListener("contextmenu", block);
      document.removeEventListener("visibilitychange", visibilityHandler);
    };
  }, [step, tabViolated]);

  /* ---------------- SUBMIT ---------------- */
  const submitTest = (forced = false) => {
    if (!forced && Object.keys(answers).length < 50) {
      alert("Please answer all 50 questions.");
      return;
    }
    localStorage.removeItem(STORAGE_KEY);
    setStep("submitted");
  };

  /* ---------------- TIMER FORMAT ---------------- */
  const minutes = String(Math.floor(timer / 60)).padStart(2, "0");
  const seconds = String(timer % 60).padStart(2, "0");

  /* ---------------- LOGIN PAGE ---------------- */
  if (step === "login") {
    return (
      <CenteredCard title="Python Online Assessment">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            setStep("instructions");
          }}
          className="space-y-4"
        >
          <Input placeholder="Full Name" />
          <Input placeholder="Email ID" />
          <Input placeholder="Mobile Number" />
          <Input placeholder="College / Company" />
          <PrimaryButton>Proceed to Instructions</PrimaryButton>
        </form>
      </CenteredCard>
    );
  }

  /* ---------------- INSTRUCTIONS PAGE ---------------- */
  if (step === "instructions") {
    return (
      <CenteredCard title="Test Instructions">
        <div className="space-y-3 text-sm text-gray-700">
          <Instruction>50 questions – all mandatory</Instruction>
          <Instruction>Time limit: 20 minutes</Instruction>
          <Instruction>No copy, paste or right click</Instruction>
          <Instruction>No tab switching</Instruction>
          <Instruction>Auto submit on timeout</Instruction>
        </div>

        <PrimaryButton
          className="mt-6"
          onClick={() => {
            if (!questions.length) generateQuestions();
            setStep("test");
          }}
        >
          Start Test
        </PrimaryButton>
      </CenteredCard>
    );
  }

  /* ---------------- TEST PAGE ---------------- */
  if (step === "test") {
    return (
      <div className="min-h-screen bg-gray-100 px-3 py-4">
        {/* HEADER */}
        <div className="sticky top-0 z-10 bg-white rounded-xl shadow flex justify-between px-4 py-3 mb-4">
          <h2 className="font-bold text-lg">Python Test</h2>
          <span className="px-4 py-1 rounded-full bg-red-100 text-red-600 font-bold">
            ⏱ {minutes}:{seconds}
          </span>
        </div>

        {/* QUESTIONS */}
        <div className="max-w-3xl mx-auto">
          {questions.map((q, i) => (
            <div
              key={q.id}
              className="bg-white p-5 rounded-xl shadow mb-5"
            >
              <p className="font-semibold mb-4">
                {i + 1}. {q.question}
              </p>

              <div className="grid gap-3">
                {q.options.map((opt) => (
                  <button
                    key={opt}
                    type="button"
                    onClick={() =>
                      setAnswers((prev) => ({
                        ...prev,
                        [q.id]: opt,
                      }))
                    }
                    className={`w-full text-left px-4 py-3 rounded-lg border transition ${
                      answers[q.id] === opt
                        ? "bg-blue-600 text-white border-blue-600"
                        : "bg-white border-gray-300 hover:bg-blue-50"
                    }`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}

          {/* SUBMIT */}
          <button
            onClick={() => submitTest()}
            className="w-full bg-green-600 text-white py-3 rounded-xl font-bold text-lg hover:bg-green-700"
          >
            Submit Test
          </button>
        </div>
      </div>
    );
  }

  /* ---------------- SUBMITTED ---------------- */
  return (
    <CenteredCard title="Test Submitted 🎉">
      <p className="text-center text-gray-600">
        Thank you for attending the Python assessment.
      </p>
    </CenteredCard>
  );
}

/* ---------------- UI COMPONENTS ---------------- */

const CenteredCard = ({ title, children }) => (
  <div className="min-h-screen flex items-center justify-center bg-gray-100 px-3">
    <div className="bg-white p-6 rounded-2xl shadow w-full max-w-lg">
      <h2 className="text-xl font-bold text-center mb-5">{title}</h2>
      {children}
    </div>
  </div>
);

const Input = ({ placeholder }) => (
  <input
    required
    placeholder={placeholder}
    className="w-full border px-3 py-2 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
  />
);

const PrimaryButton = ({ children, onClick, className = "" }) => (
  <button
    onClick={onClick}
    className={`w-full bg-blue-600 text-white py-2 rounded-lg font-semibold hover:bg-blue-700 ${className}`}
  >
    {children}
  </button>
);

const Instruction = ({ children }) => (
  <div className="flex gap-2">
    <span className="text-blue-600 font-bold">•</span>
    <span>{children}</span>
  </div>
);
